static int _getFlags(OpenMode openMode, AccessMode accessMode) {
    int mode = 0;
    if (openMode & OM_CREATE) {
        mode |= LFS_O_CREAT;
    }
    if (openMode & OM_APPEND) {
        mode |= LFS_O_APPEND;
    }
    if (openMode & OM_TRUNCATE) {
        mode |= LFS_O_TRUNC;
    }
    if (accessMode & AM_READ) {
        mode |= LFS_O_RDONLY;
    }
    if (accessMode & AM_WRITE) {
        mode |= LFS_O_WRONLY;
    }
    return mode;
}

